mapper.select:
SELECT PRD.FINPROD_ID as finprodId,PRD.FINPROD_TYPE as finprodType,PRD.branch FROM ( SELECT T.FINPROD_ID, T.FINPROD_TYPE, 0 branch FROM FIN_PRODUCT T WHERE T.FINPROD_TYPE IN ('F16','F26') UNION ALL SELECT A.ACCT_SUBJECT_ID, A.ACCT_SUBJECT_TYPE, 0 as branch FROM BOK_ACCT_SUBJECT_INFO A LEFT JOIN BOK_BOOKSET BOK ON A.ACCT_SUBJECT_ID = BOK.ACCT_SUBJECT_ID AND A.ACCT_SUBJECT_TYPE = BOK.ACCT_SUBJECT_TYPE WHERE A.ACCT_SUBJECT_TYPE IN ('F18','F26') UNION ALL SELECT B.FINPROD_ID, B.FINPROD_TYPE, round(date_format(B.VDATE,'%Y%m%d')) as branch FROM FIN_TRADE_PRODUCT B WHERE B.FINPROD_TYPE = 'F22' ) PRD WHERE PRD.FINPROD_ID = #{finprodId}
AND PRD.FINPROD_TYPE = #{finprodType }
AND PRD.branch = #{branch }
